class Solution {
public:
    int minOperations(vector<int>& nums, int target) {
        long long total = 0;
        for (int x : nums) total += x;
        if (total < target) return -1;
        vector<int> count(32, 0);
        for (int x : nums) {
            int bit = 0;
            while ((1LL << bit) < x) bit++;
            count[bit]++;
        }
        int ops = 0;
        for (int i = 0; i < 31; i++) {
            if ((target >> i) & 1) {
                if (count[i] > 0) {
                    count[i]--;
                } else {
                    int j = i;
                    while (j < 31 && count[j] == 0) j++;
                    while (j > i) {
                        count[j]--;
                        count[j - 1] += 2;
                        ops++;
                        j--;
                    }
                    count[i]--;
                }
            }
            count[i + 1] += count[i] / 2;
        }
        return ops;
    }
};

