var minOperations = function(nums, target) {
    let total = 0;
    for (const x of nums) total += x;
    if (total < target) return -1;
    const count = new Array(32).fill(0);
    for (const x of nums) {
        let bit = 0;
        while ((1 << bit) < x) bit++;
        count[bit]++;
    }
    let ops = 0;
    for (let i = 0; i < 31; i++) {
        if ((target >> i) & 1) {
            if (count[i] > 0) {
                count[i]--;
            } else {
                let j = i;
                while (j < 31 && count[j] === 0) j++;
                while (j > i) {
                    count[j]--;
                    count[j - 1] += 2;
                    ops++;
                    j--;
                }
                count[i]--;
            }
        }
        count[i + 1] += Math.floor(count[i] / 2);
    }
    return ops;
};
